const tabID = "tab_f624a047-074f-4ec0-9747-6da15bcb846c"
const info = await tools.browser.evaluate({ tabID, fn: `() => {
  const w = window.innerWidth;
  const slogan = document.querySelector('.slogan-box');
  const title = document.querySelector('h1.main-title');
  const left = document.querySelector('.hero-left');
  const right = document.querySelector('.hero-right');
  const r = el => { const b = el.getBoundingClientRect(); return {top: Math.round(b.top + scrollY), left: Math.round(b.left), right: Math.round(b.right), bottom: Math.round(b.bottom + scrollY)}; };
  return JSON.stringify({innerWidth: w, slogan: r(slogan), title: r(title), heroLeft: r(left), heroRight: r(right)});
}` })
return info

