/* ===== Sections de contenu ===== */
.content-section {
  max-width: 1100px;
  margin: 0 auto;
  padding: 80px 40px 0 40px;
}

.content-section h2 {
  font-size: 2rem;
  color: #e2e8f0;
  margin-bottom: 35px;
  letter-spacing: -0.5px;
}

/* Citation choc */
.quote-band {
  max-width: 900px;
  margin: 0 auto;
  padding: 90px 40px 0 40px;
  text-align: center;
}

blockquote.big-quote {
  font-size: 1.7rem;
  line-height: 1.55;
  color: #e2e8f0;
  font-style: italic;
  position: relative;
}

blockquote.big-quote::before {
  content: '\201C';
  display: block;
  font-size: 5rem;
  line-height: 1;
  color: #1f5e71;
  font-style: normal;
  margin-bottom: 10px;
}

blockquote.big-quote footer {
  margin-top: 20px;
  font-size: 0.9rem;
  font-style: normal;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #64748b;
}

/* Fiche du livre */
.specs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.spec-tile {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 14px;
  padding: 25px 20px;
  text-align: center;
  transition: transform 0.3s cubic-bezier(0.165, 0.84, 0.44, 1), border-color 0.3s;
}

.spec-tile:hover {
  transform: translateY(-4px);
  border-color: rgba(31, 94, 113, 0.6);
}

.spec-tile .spec-value {
  font-size: 1.15rem;
  font-weight: 700;
  color: #bdb292;
  margin-bottom: 6px;
}

.spec-tile .spec-key {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #64748b;
}

/* Cartes "Pour les lecteurs de" */
.vibes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 25px;
}

.vibe-card {
  background: linear-gradient(160deg, rgba(31, 94, 113, 0.12), rgba(255, 255, 255, 0.02));
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 14px;
  padding: 30px;
  transition: transform 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);
}

.vibe-card:hover {
  transform: translateY(-6px);
}

.vibe-card h3 {
  font-size: 1.3rem;
  color: #4da9d3;
  margin-bottom: 10px;
}

.vibe-card p {
  font-size: 0.95rem;
  color: #94a3b8;
  line-height: 1.6;
}

.section-cta {
  margin-top: 30px;
  text-align: center;
}

/* Bio de l'auteur */
.author-bio {
  display: flex;
  gap: 40px;
  align-items: flex-start;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 16px;
  padding: 40px;
}

.author-monogram {
  flex-shrink: 0;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #1f5e71, #0b0c10);
  border: 2px solid rgba(189, 178, 146, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.2rem;
  font-weight: 900;
  color: #bdb292;
  letter-spacing: 2px;
}

.author-bio-text p {
  color: #94a3b8;
  line-height: 1.7;
  margin-bottom: 12px;
}

.author-bio-text .bio-sign {
  color: #bdb292;
  font-style: italic;
}

/* La saga */
.series-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 25px;
}

.series-card {
  border-radius: 16px;
  padding: 35px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
  position: relative;
  overflow: hidden;
}

.series-card.current {
  background: linear-gradient(160deg, rgba(31, 94, 113, 0.18), rgba(255, 255, 255, 0.02));
  border-color: rgba(31, 94, 113, 0.5);
}

.series-card .series-num {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #64748b;
  margin-bottom: 8px;
}

.series-card h3 {
  font-size: 1.5rem;
  color: #e2e8f0;
  margin-bottom: 10px;
}

.series-card p {
  color: #94a3b8;
  margin-bottom: 20px;
}

.series-badge {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  padding: 5px 12px;
  border-radius: 20px;
  margin-bottom: 15px;
}

.series-badge.out {
  background: rgba(189, 178, 146, 0.15);
  color: #bdb292;
}

.series-badge.soon {
  background: rgba(77, 169, 211, 0.12);
  color: #4da9d3;
}

/* Newsletter */
.newsletter-band {
  max-width: 900px;
  margin: 0 auto;
  padding: 90px 40px 90px 40px;
  text-align: center;
}

.newsletter-band h2 {
  font-size: 2rem;
  color: #e2e8f0;
  margin-bottom: 12px;
}

.newsletter-band p {
  color: #94a3b8;
  margin-bottom: 30px;
}

.btn-newsletter {
  display: inline-block;
  padding: 13px 34px;
  border-radius: 10px;
  background: #1f5e71;
  color: #e2e8f0;
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);
  box-shadow: 0 4px 25px rgba(31, 94, 113, 0.35);
}

.btn-newsletter:hover {
  background: #2a7d95;
  transform: translateY(-2px);
}

/* Apparition au défilement */
.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.reveal.visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

