const tab = await tools.browser.tabs.open({ url: "http://127.0.0.1:8741/scarcity-fr.html" })
await tools.browser.wait({ tabID: tab.id, condition: "load" })
await tools.browser.tabs.focus({ tabID: tab.id })
const errs = await tools.browser.console({ tabID: tab.id, level: "error" })
const shot = await tools.browser.screenshot({ tabID: tab.id })
return { errors: errs.messages.map(m => m.text), shot }

const tabEN = await tools.browser.tabs.open({ url: "http://127.0.0.1:8741/index.html" })
await tools.browser.wait({ tabID: tabEN.id, condition: "load" })
await tools.browser.tabs.focus({ tabID: tabEN.id })
const shotEN = await tools.browser.screenshot({ tabID: tabEN.id })
// vue mobile simulée : réduire la fenêtre n'est pas possible, mais on vérifie le DOM responsive
const tabFR = "tab_f4c4025f-4f12-486e-8512-e58f8b6c7243"
const check = await tools.browser.evaluate({
  tabID: tabFR,
  script: `JSON.stringify({
    video: !!document.querySelector('.video-banner video'),
    videoSrc: document.querySelector('.video-banner video source') ? document.querySelector('.video-banner video source').getAttribute('src') : '-',
    kicker: document.querySelector('.banner-kicker') ? document.querySelector('.banner-kicker').textContent : '-',
    title: document.querySelector('.banner-title') ? document.querySelector('.banner-title').textContent : '-',
    logo: document.querySelector('.nav-logo').textContent,
    tabsLeft: [...document.querySelectorAll('.nav-left a')].map(a => a.textContent),
    contact: document.querySelector('.nav-right a').getAttribute('href')
  })`
})
return { check: check.value, shotEN }

