cd /Users/fouick/Documents/GitHub/storytellise && python3 - <<'EOF'
import re

def parse_extract(path):
    txt = open(path).read()
    # normaliser : lignes avec tabulations = paragraphes
    lines = [l.strip() for l in txt.split("\n")]
    lines = [l for l in lines if l and l != "_"]
    title = lines[0]
    date = lines[1]
    paras = lines[2:]
    return title, date, paras

def esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def build_reading(src_page, out_page, lang, title_pg, meta_desc, nav_home, nav_lang, nav_lang_href,
                  extract_path, readmore_label, buy_label, buy_href, end_note, teaser_word):
    title, date, paras = parse_extract(extract_path)
    head = open(src_page).read().split("<main>")[0]
    tail = open(src_page).read().split("</main>")[1]
    head = re.sub(r'<html lang="[^"]*">', '<html lang="%s">' % lang, head)
    head = re.sub(r'<title>.*?</title>', '<title>%s</title>' % title_pg, head, count=1, flags=re.S)
    if '<meta name="description"' in head:
        head = re.sub(r'<meta name="description" content="[^"]*">',
                      '<meta name="description" content="%s">' % meta_desc, head)

    body_paras = []
    for i, p in enumerate(paras):
        cls = ' class="drop-cap"' if i == 0 else ""
        body_paras.append("        <p%s>%s</p>" % (cls, esc(p)))
    body = "\n".join(body_paras)

    # CSS de lecture insérée avant </style> dans le head
    reading_css = """
    /* Page lecture */
    .chapter-title {
      font-size: 2.5rem;
      color: #e2e8f0;
      letter-spacing: -0.5px;
      margin-bottom: 6px;
    }
    .chapter-date {
      color: #64748b;
      font-style: italic;
      font-size: 1.05rem;
    }
    .reading-text {
      max-width: 680px;
      margin: 45px auto 0 auto;
      font-size: 1.13rem;
      line-height: 1.9;
      color: #c9cfd6;
    }
    .reading-text p {
      margin-bottom: 1.15em;
      text-align: justify;
    }
    .drop-cap::first-letter {
      font-size: 3.1em;
      float: left;
      line-height: 0.82;
      padding: 0.05em 0.09em 0 0;
      color: #bdb292;
      font-weight: 700;
    }
    .excerpt-end {
      text-align: center;
      margin-top: 60px;
      padding-top: 40px;
      border-top: 1px solid rgba(255, 255, 255, 0.07);
    }
    .excerpt-end-note {
      color: #94a3b8;
      font-style: italic;
      font-size: 1.05rem;
      margin-bottom: 22px;
    }
    @media (max-width: 968px) {
      .reading-text { font-size: 1.05rem; line-height: 1.8; }
      .reading-text p { text-align: left; }
      .chapter-title { font-size: 1.9rem; }
    }
"""
    head = head.replace("</style>", reading_css + "  </style>")

    main = """
  <main>
    <section class="content-section reveal" id="extrait" style="padding-top: 140px;">
      <div class="section-label">%(label)s</div>
      <h1 class="chapter-title">%(ctitle)s</h1>
      <div class="chapter-date">%(cdate)s</div>
      <div class="reading-text">
%(body)s
      </div>
      <div class="excerpt-end reveal">
        <div class="excerpt-end-note">%(end_note)s</div>
        <a href="%(buy_href)s" target="_blank" class="btn-action btn-amazon">%(buy_label)s</a>
      </div>
    </section>
  </main>""" % dict(label=teaser_word, ctitle=esc(title), cdate=esc(date), body=body,
                    end_note=end_note, buy_href=buy_href, buy_label=buy_label)
    open(out_page, "w").write(head + main + tail)
    print(out_page, ":", len(paras), "paragraphes")

