cd /Users/fouick/Documents/GitHub/storytellise && python3 - <<'EOF'
import re

def clean(p):
    p = re.sub(r'<span[^>]*>', '', p)
    p = p.replace('</span>', '')
    p = re.sub(r'<br\s*/?>', '<br />', p)
    p = re.sub(r'<(?!/?[iIbB]|br\s|/br)[^>]+>', '', p)
    return p.strip()

def parse_body(path):
    html = open(path).read()
    seq = []
    for m in re.finditer(r'<p[^>]*>.*?</p>|<table.*?</table>', html, flags=re.S):
        block = m.group(0)
        if block.startswith('<table'):
            # cellule unique : joindre les <p> internes avec des <br>
            inner = re.findall(r'<p[^>]*>(.*?)</p>', block, flags=re.S)
            lines = [clean(x) for x in inner if clean(x)]
            content = '<br />'.join(lines)
            seq.append(('table', content))
        else:
            content = clean(re.sub(r'^<p[^>]*>|</p>$', '', block, flags=re.S))
            if not content or content == '_':
                continue
            seq.append(('p', content))
    return seq

def rebuild(page, odt_html):
    seq = parse_body(odt_html)
    body = seq[2:]  # titre + date sautés
    out = []
    for i, (kind, content) in enumerate(body):
        if kind == 'table':
            out.append('        <div class="messpam">%s</div>' % content)
        else:
            cls = ' class="drop-cap"' if i == 0 and not out else ''
            out.append('        <p%s>%s</p>' % (cls, content))
    html = open(page).read()
    start = html.index('<div class="reading-text">')
    end = html.index('      </div>', start)
    new_block = '<div class="reading-text">\n' + '\n'.join(out) + '\n'
    html = html[:start] + new_block + html[end:]
    # CSS du bloc message (bordures blanches)
    messpam_css = """
    .messpam {
      border: 2px solid #e2e8f0;
      border-radius: 10px;
      padding: 16px 20px;
      margin: 1.4em auto;
      background: rgba(255, 255, 255, 0.04);
      text-indent: 0 !important;
      font-size: 0.95em;
      line-height: 1.65;
      max-width: 540px;
    }
"""
    if '.messpam' not in html:
        html = html.replace('.drop-cap::first-letter {', messpam_css + '    .drop-cap::first-letter {')
    open(page, 'w').write(html)
    n_tables = sum(1 for k, _ in body if k == 'table')
    print(page, ':', len(body), 'éléments dont', n_tables, 'messages Messpam')

