import re
def clean(p):
    p = re.sub(r'<span[^>]*>', '', p); p = p.replace('</span>', '')
    p = re.sub(r'<br\s*/?>', '<br />', p)
    p = re.sub(r'<(?!/?[iIbB]|br\s|/br)[^>]+>', '', p)
    return p.strip()
html = open("/tmp/opencode/extract_fr.html").read()
seq = []
for m in re.finditer(r'<p[^>]*>.*?</p>|<table.*?</table>', html, flags=re.S):
    block = m.group(0)
    if block.startswith('<table'):
        seq.append(('table', '(MESSPAM)'))
    else:
        content = clean(re.sub(r'^<p[^>]*>|</p>$', '', block, flags=re.S))
        seq.append(('p', content[:50]))
for i, (k, c) in enumerate(seq[:6]):
    print(i, k, '|', repr(c))
EOF

