      #cookie-banner { flex-direction: column; align-items: stretch; text-align: center; }
      .cookie-actions { justify-content: center; }
    }"""
new_mobile = """    @media (max-width: 968px) {
      #cookie-banner { flex-direction: column; align-items: stretch; text-align: center; padding: 12px 18px; }
      .cookie-actions { justify-content: center; }
    }"""
for p in ["scarcity-fr.html", "index.html", "auteur.html", "author.html", "extrait.html", "excerpt.html"]:
    h = open(p).read()
    assert old_css in h, p + " css"
    h = h.replace(old_css, new_css)
    if old_mobile in h:
        h = h.replace(old_mobile, new_mobile)
    open(p, "w").write(h)
    print(p, "✓ bandeau full-width une ligne")
